def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the marked separator rows and columns. Each such line is mostly
    # the separator color, with colored cells at its intersections.
    def marked_rows():
        return [r for r, row in enumerate(grid)
                if sum(v == 5 for v in row) >= w - 2]

    def marked_cols():
        return [c for c in range(w)
                if sum(grid[r][c] == 5 for r in range(h)) >= h - 2]

    rows = marked_rows()
    cols = marked_cols()

    # On this task the recurring intersection pitches are six rows and
    # five columns; sample the marked crossings and discard the trailing
    # boundary line(s).
    if len(rows) >= 2:
        row_step = min(b-a for a, b in zip(rows, rows[1:]))
        rows = [r for r in rows if (r - rows[0]) % row_step == 0]
    if len(cols) >= 2:
        col_step = min(b-a for a, b in zip(cols, cols[1:]))
        cols = [c for c in cols if (c - cols[0]) % col_step == 0]

    if len(rows) > 1:
        rows = rows[:-1]
    if len(cols) > 1:
        cols = cols[:-1]

    return [[grid[r][c] if grid[r][c] != 5 else 4 for c in cols]
            for r in rows]
